function validate([richer, quiet]) {
  const n = quiet.length;
  if (n < 1 || n > 500) return 'quiet needs 1 to 500 people.';
  if (quiet.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'Each quiet value is from 0 to n - 1.';
  if (new Set(quiet).size !== n) return 'All quiet values must be different.';
  const seen = new Set();
  const indegree = new Array(n).fill(0);
  const out = Array.from({ length: n }, () => []);
  for (const pair of richer) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each fact is a pair [a, b].';
    const [a, b] = pair;
    if (![a, b].every(v => Number.isInteger(v) && v >= 0 && v < n)) return 'People in richer are numbered 0 to n - 1.';
    if (a === b) return 'A fact must name two different people.';
    if (seen.has(a * n + b)) return 'Each fact appears only once.';
    seen.add(a * n + b);
    out[a].push(b);
    indegree[b]++;
  }
  // The facts must not loop back on themselves.
  const queue = [];
  for (let i = 0; i < n; i++) if (indegree[i] === 0) queue.push(i);
  let visited = 0;
  for (let head = 0; head < queue.length; head++) {
    visited++;
    for (const next of out[queue[head]]) if (--indegree[next] === 0) queue.push(next);
  }
  if (visited !== n) return 'The facts in richer contradict each other (they form a cycle).';
  return null;
}

