function loudAndRich(richer, quiet) {
  const n = quiet.length;
  const richerThan = Array.from({ length: n }, () => []);
  for (const [rich, poor] of richer) {
    richerThan[poor].push(rich);
  }
  const answer = new Array(n).fill(-1);

  const dfs = (person) => {
    if (answer[person] !== -1) {
      return answer[person];
    }
    answer[person] = person;
    for (const other of richerThan[person]) {
      const candidate = dfs(other);
      if (quiet[candidate] < quiet[answer[person]]) {
        answer[person] = candidate;
      }
    }
    return answer[person];
  };

  for (let person = 0; person < n; person++) {
    dfs(person);
  }
  return answer;
}

