function loudAndRich(richer, quiet) {
  // Build the full "at least as rich" relation with a transitive closure, then scan each column.
  const n = quiet.length;
  const atLeast = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => i === j));
  for (const [a, b] of richer) atLeast[a][b] = true;
  for (let k = 0; k < n; k++)
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++)
        if (atLeast[i][k] && atLeast[k][j]) atLeast[i][j] = true;
  const result = [];
  for (let x = 0; x < n; x++) {
    let best = x;
    for (let y = 0; y < n; y++) if (atLeast[y][x] && quiet[y] < quiet[best]) best = y;
    result.push(best);
  }
  return result;
}

