function generate(rand, size) {
  const n = size === 'large' ? 500 : 1 + Math.floor(rand() * 7);
  const shuffle = (list) => {
    for (let i = list.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [list[i], list[j]] = [list[j], list[i]];
    }
    return list;
  };
  // A hidden wealth order keeps every fact consistent: wealth[0] is the richest person.
  const wealth = shuffle(Array.from({ length: n }, (_, i) => i));
  const quiet = shuffle(Array.from({ length: n }, (_, i) => i));
  const maxPairs = n * (n - 1) / 2;
  const target = size === 'large' ? 2000 : Math.floor(rand() * (maxPairs + 1));
  const used = new Set();
  const richer = [];
  // Large inputs often include the full chain, so the facts reach 500 levels deep.
  if (size === 'large' && rand() < 0.5) {
    for (let i = 0; i + 1 < n; i++) {
      used.add(wealth[i] * n + wealth[i + 1]);
      richer.push([wealth[i], wealth[i + 1]]);
    }
  }
  while (richer.length < target) {
    const i = Math.floor(rand() * n);
    const j = Math.floor(rand() * n);
    if (i === j) continue;
    const a = wealth[Math.min(i, j)];
    const b = wealth[Math.max(i, j)];
    if (used.has(a * n + b)) continue;
    used.add(a * n + b);
    richer.push([a, b]);
  }
  return [shuffle(richer), quiet];
}
